 y=t.exploratory_target_fraction.to_numpy();code=t.stage_number.to_numpy()-1;counts=np.bincount(code,minlength=L);groups=[y[code==i] for i in range(L)];assert (counts>0).all();kw=kruskal(*groups);ranks=rankdata(y);_,ties=np.unique(y,return_counts=True);N=len(y);tiecor=1-np.sum(ties.astype(float)**3-ties)/(N**3-N);rank_sums=np.bincount(code,weights=ranks,minlength=L);manual=(12/(N*(N+1))*np.sum(rank_sums**2/counts)-3*(N+1))/tiecor;assert np.isclose(manual,kw.statistic,atol=1e-10);sp=spearmanr(t.stage_number,y);stage_ranks=rankdata(code);ac=stage_ranks-stage_ranks.mean();yc=ranks-ranks.mean();den=np.linalg.norm(ac)*np.linalg.norm(yc);manualrho=float(np.dot(ac,yc)/den);assert np.isclose(manualrho,sp.statistic,atol=1e-12);flag=y>0;table=np.column_stack([np.bincount(code,weights=flag,minlength=L),np.bincount(code,weights=~flag,minlength=L)]);ch=chi2_contingency(table,correction=False);expected=ch.expected_freq;kh=st=ct=0;rng=np.random.default_rng(seed)
